WITH valid AS (SELECT *, IF(is_flagged, 'Yes', 'No') AS is_flagged_label, CASE WHEN amount >= 3500 THEN 'High' WHEN amount >= 1100 THEN 'Medium' ELSE 'Low' END AS amount_tier FROM transactions WHERE merchant NOT IN ('Amazon', '7-Eleven')), gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) > INTERVAL 14 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM valid), sessions_transactions AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, is_flagged_label, SUM(new_group_flag) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT merchant, SORT_ARRAY(COLLECT_SET(merchant)) AS merchant_list, COUNT(*) FILTER (WHERE txn_type = 'REFUND') AS refund_rows, MIN(txn_time) AS first_txn_time, SORT_ARRAY(COLLECT_SET(merchant)) AS merchant_list_2 FROM sessions_transactions GROUP BY merchant
